    core::ptr::slice_from_raw_parts_mut(trace.c1[9].as_ptr() as *mut u32, trace.c1[9].len()),
    core::ptr::slice_from_raw_parts_mut(trace.c1[10].as_ptr() as *mut u32, trace.c1[10].len()),
