/// D18's arithmetic digit permutation, on the admitted row domain 0..1024.
pub fn row_arithmetic(j: usize) -> usize {
    64 * (j % 4) + 256 * ((j / 4) % 4) + 16 * ((j / 16) % 4)
        + ((j / 64) % 4) + 4 * ((j / 256) % 4)
}

